<?php declare(strict_types=1); namespace Modules\Authentication\Controllers\Api; use App\Http\Controllers\Controller; use Core\Auth\Auth; use Core\Http\ApiResponse; use Core\Http\JsonResponse; use Core\Http\Request; class ApiAuthController extends Controller { public function __construct(private readonly Auth $auth) { } public function login(Request $request): JsonResponse { $data = $request->validate([ 'email' => 'required|email', 'password' => 'required|string', ]); if (!$this->auth->attempt((string) $data['email'], (string) $data['password'])) { return ApiResponse::error(trans('auth.failed'), [], 401, 'unauthenticated'); } return ApiResponse::success([ 'user' => $this->auth->user()?->toArray() ?? [], ], trans('auth.welcome')); } public function logout(): JsonResponse { $this->auth->logout(); return ApiResponse::success(null, trans('auth.logged_out')); } public function me(): JsonResponse { $user = $this->auth->user(); return ApiResponse::success([ 'user' => $user !== null && method_exists($user, 'toArray') ? $user->toArray() : (array) $user, ]); } } 